import { type BuiltinToolResults, type EngineInterface, type On, type PluginOptions, type Timer, update } from 'claude-code'
import type { AbovePromptEvent, AbovePromptNext, AbovePromptResult, PartEvent, PartNext, PartResult } from '../parts'
import { LINUX_LAUNCH, openCommand, openWithCommand, tmuxOpenCommand } from './open'
import type { ButtonProps } from './button'

import type { Activity, FileNode, FileTree } from '../../types'
import { BRANCH_ICON, chainOf, type GitAction, gitActions, readOnly, readTargets, resolve } from './git'
import type { RowSpec, RowsProps, Seg } from './rows'
import { CHEVRON_CLOSED, CHEVRON_OPEN, fileCategory, fileIcon } from './icons'
import { defaultLook, pernambucoLook } from './look'
import { DEFAULT_PREFS } from '../command'
import {
  age,
  ancestorsOf,
  type Change,
  DEFAULT_THEME,
  dirname,
  emptyTree,
  formatSize,
  inside,
  isAbsolute,
  join,
  LIGHT_THEME,
  mapper,
  parseGit,
  parseNumstat,
  parseTheme,
  posix,
  relative,
  dropBelow,
