          <Button key="nav-s" plain dimColor hotkey="s" label={unicode ? 'buscar' : '\u{f0349} buscar'} onPress={() => void $.ui.focus({ requestId: PANE, key: 'q' })} />
        </Box>
        <Client
          key="rows"
          module="./rows.tsx"
          props={{ rows: specs, active: t.cursor, ...rowColors, pointer, ...(bar ? { bar } : {}) } satisfies RowsProps}
