import { atom, read, update } from 'claude-code'
import type { ElementTable, EngineInterface, On, PluginOptions } from 'claude-code'
import type { AbovePromptEvent, AbovePromptNext, AbovePromptResult, PartEvent, PartNext, PartResult } from '../parts'

import type { AgentRun, Flow, Panel, PlannedTask, TaskItem } from '../../types'
import { TOKENS } from '../pe/ds.generated'
import { halfBlocks, LIS_BODY, LIS_PALETTE, LIS_TERMINAL } from './lis'
import type { Cell } from './lis'
import { applyTaskCall, crewFlow, flowOf } from './tasks'

const flow = atom({ plugin: 'pe-devkit', key: 'progressFlow' } as const, null)
const agents = atom({ plugin: 'pe-devkit', key: 'progressAgents' } as const, [])
// How many agents there were when the agents bar was dismissed; a new agent brings it back.
const crewHidden = atom({ plugin: 'pe-devkit', key: 'progressCrewHidden' } as const, -1)
const panel = atom({ plugin: 'pe-devkit', key: 'progressPanel' } as const, {
  isCompact: false,
  isDoneCollapsed: false,
  autoOpenedFor: '',
})
const now = atom({ plugin: 'pe-devkit', key: 'progressNow' } as const, 0)
const tasks = atom({ plugin: 'pe-devkit', key: 'progressTasks' } as const, [] as TaskItem[])

const PANE = 'progress-agents'
const L = TOKENS.light
const D = TOKENS.dark
const TASK_TOOLS = /^(TaskCreate|TaskUpdate|TodoWrite|TaskList)$/
// Liga Digital tokens: the bar in the primary blue, a finished bar in the success green.
const ACCENT = TOKENS.dark['--color-text-primary']!
const DONE = TOKENS.dark['--color-text-success']!

const STRINGS = {
  pane: 'Agentes',
  cost: 'Custo',
  tokens: 'Tokens',
  time: 'Tempo',
  collapse: 'Recolher',
  expand: 'Expandir',
  running: 'Rodando',
  finished: 'Concluídos',
  planned: 'Planejados',
  empty: 'Nenhum subagente ainda.',
  round: 'rodada',
  failed: 'erro',
  after: 'depois de',
  tokensWord: 'tokens',
  agentsCount: 'agentes',
  isRunning: 'rodando',
  isFinished: 'concluído',
  isPlanned: 'planejado',
  opened: 'Painel de agentes aberto.',
  closed: 'Painel de agentes fechado.',
  done: 'Concluído',
  plan: 'Plano',
  design: 'Design',
  tasks: 'Tarefas',
  review: 'Revisão',
  busy: 'em andamento',
  ctx: 'ctx',
  tier: { light: 'leve', medium: 'médio', careful: 'cuidadoso', heavy: 'pesado', fable: 'fable', other: 'outro' },
  effort: { low: 'baixo', medium: 'médio', high: 'alto', xhigh: 'muito alto', max: 'máximo' },
} as const

const tr = () => STRINGS

// Tier and effort words as shown; anything unknown shows as it came.
const tierWord = (tier: string): string => (tr().tier as Record<string, string>)[tier] ?? tier
const effortWord = (effort: string): string => (tr().effort as Record<string, string>)[effort] ?? effort

const label = (f: Flow): string => {
  const s = tr()
  if (f.isFinished) return s.done
  if (f.phase === 'plan') return s.plan
  if (f.phase === 'design') return s.design
  if (f.phase === 'agents') return `${s.pane} ${f.done}/${f.total}`
  const count = f.total ? `${f.done}/${f.total}` : `${f.running} ${s.busy}`
  return `${f.phase === 'review' ? s.review : s.tasks} ${count}`
}

const ratio = (f: Flow): number => (f.isFinished ? 1 : f.total ? f.done / f.total : 0)

// Deterministic noise so the dither does not shimmer between redraws.
const noise = (x: number, y: number): number => {
  const s = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453
  return s - Math.floor(s)
}

// The whole row is one SVG: the desktop wraps sibling elements onto new lines,
// so title, bar, percent and the crab live in one drawing; only the count and
// the dismiss are Buttons beside it.
const H = 22
const BAR_H = 16
const CRAB_W = 26
// The crab's drawing grid is 30 units wide, props included.
const CRAB_BOX = 30
const CELL = 3
const FONT = "-apple-system,BlinkMacSystemFont,'SF Pro Text','Segoe UI',sans-serif"

const xml = (s: string): string =>
  s.replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c] ?? c)

const clip = (s: string, max: number): string => (s.length > max ? s.slice(0, Math.max(1, max - 1)) + '…' : s)

// CJK, fullwidth forms and emoji advance about 1em; at 0.56em a Chinese title was sized at half its width and the bar drew over it.
// 中日韩文字、全角标点和 emoji 约占 1em；按 0.56em 算时中文标题宽度被低估近一半，进度条会压到标题上。
const WIDE =
  /[\u1100-\u115F\u2E80-\u303E\u3041-\u33FF\u3400-\u4DBF\u4E00-\u9FFF\uA960-\uA97F\uAC00-\uD7A3\uF900-\uFAFF\uFE30-\uFE4F\uFF01-\uFF60\uFFE0-\uFFE6\u{1F300}-\u{1FAFF}\u{20000}-\u{3FFFD}]/u

// Rough advance of system UI text, in em; good enough to size the title's slot.
const charEm = (ch: string): number =>
  WIDE.test(ch) ? 1 : /[\s.,:;'|!il1()[\]]/.test(ch) ? 0.3 : /[A-ZА-ЯЁmwшщжюМШЩЖЮ@%]/.test(ch) ? 0.72 : 0.56

const textWidth = (s: string, size: number): number => [...s].reduce((w, ch) => w + charEm(ch) * size, 0)

// Cuts `s` to fit `maxW` pixels, with an ellipsis when it had to cut.
const fitText = (s: string, size: number, maxW: number): string => {
  if (textWidth(s, size) <= maxW) return s
  let out = ''
  for (const ch of s) {
    if (textWidth(out + ch + '…', size) > maxW) break
    out += ch
  }
  return out + '…'
}

// The Pernambuco flag in the bar's fill: blue over white, two thirds to one third.
const FLAG_WHITE = '#FFFFFF'
const FLAG_BLUE_H = Math.round((BAR_H * 2) / 3)
const EMBLEM_W = 10

const starPath = (cx: number, cy: number, r: number): string =>
  Array.from({ length: 10 }, (_, i) => {
    const a = -Math.PI / 2 + (i * Math.PI) / 5
    const d = i % 2 ? r * 0.42 : r
    return `${i ? 'L' : 'M'}${(cx + d * Math.cos(a)).toFixed(2)} ${(cy + d * Math.sin(a)).toFixed(2)}`
  }).join('') + 'Z'

// The rainbow arc and the star on the blue, the cross on the white, `x` at the emblem's left edge.
const flagEmblem = (x: number): string => {
  const px = (dx: number, y: number, w: number, h: number, c: string): string =>
    `<rect x="${x + dx}" y="${y}" width="${w}" height="${h}" fill="${c}"/>`
  return [
    px(2, 1, 6, 1, LIS_PALETTE.r),
    px(1, 2, 1, 2, LIS_PALETTE.r),
    px(8, 2, 1, 2, LIS_PALETTE.r),
    px(3, 2, 4, 1, LIS_PALETTE.y),
    px(2, 3, 1, 1, LIS_PALETTE.y),
    px(7, 3, 1, 1, LIS_PALETTE.y),
    px(4, 3, 2, 1, LIS_PALETTE.g),
    `<path d="${starPath(x + 5, 7, 2.8)}" fill="${LIS_PALETTE.y}"/>`,
    px(4.25, FLAG_BLUE_H, 1.5, BAR_H - FLAG_BLUE_H, LIS_PALETTE.r),
    px(2, FLAG_BLUE_H + 1.5, 6, 1.5, LIS_PALETTE.r),
  ].join('')
}

const rowSvg = (f: Flow, W: number, isWorking: boolean): string => {
  // The title takes what it needs, up to 40% of the row; the bar takes the rest.
  const title = fitText(f.title, 13, Math.max(60, W * 0.4))
  const BAR_X = Math.round(16 + textWidth(title, 13) + 12)
  const BAR_W = Math.max(60, W - BAR_X - 46 - CRAB_W)
  const color = f.isFinished ? DONE : ACCENT
  const y0 = (H - BAR_H) / 2
  const fillW = Math.round(BAR_W * ratio(f))
  const runW = f.total ? Math.round((BAR_W * Math.min(f.total, f.done + f.running)) / f.total) : 0
  const cols = Math.floor(fillW / CELL)
  const rows = Math.floor(BAR_H / CELL)
  // Handed to workers, not yet accepted: a faint second layer.
  const faint: string[] = []
  for (let c = cols; c < Math.floor(runW / CELL); c++) {
    for (let r = 0; r < rows; r++) {
      if (noise(c + 7, r + 3) < 0.2) faint.push(`<rect class="t${Math.floor(noise(r + 5, c) * 4)}" x="${c * CELL + 1}" y="${r * CELL + 1}" width="1.7" height="1.7"/>`)
    }
  }

  const ticks: string[] = []
  for (let i = 1; i < f.total; i++) {
    const x = Math.round((BAR_W * i) / f.total)
    if (x > fillW + 4) ticks.push(`<rect x="${x}" y="${BAR_H / 2 - 4}" width="1.5" height="8" rx="0.75"/>`)
  }

  const text = label(f)
  const pillW = Math.round(18 + text.length * 6.6)
  const pillX = Math.max(0, Math.min(BAR_W - pillW, fillW - pillW))
  const percent = `${Math.round(ratio(f) * 100)}%`
  const titleAt = 'x="16"'
  const percentAt = `x="${W - CRAB_W - 6}" y="${H / 2 + 4.5}" text-anchor="end"`
  const emblem = fillW - pillW >= EMBLEM_W + 2 ? flagEmblem(pillX - EMBLEM_W - 2) : ''

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
<style>
.t{fill:${L['--color-text-default']}}.m{fill:${L['--color-text-secondary']}}.k{fill:${L['--color-light-gray-softer']}}.tk{fill:${L['--color-light-gray-soft']}}
@media (prefers-color-scheme: dark){.t{fill:${D['--color-text-default']}}.m{fill:${D['--color-text-placeholder']}}.k{fill:${D['--color-dark-gray-soft']}}.tk{fill:${D['--color-dark-gray-softest']}}}
/* Pixels twinkle in four out-of-phase groups; a finished bar settles to a slow glow. */
.t0,.t1,.t2,.t3{animation:tw ${f.isFinished ? 3.2 : 2.2}s ease-in-out infinite}
.t1{animation-duration:${f.isFinished ? 3.8 : 2.8}s;animation-delay:-.7s}.t2{animation-duration:${f.isFinished ? 4.4 : 1.9}s;animation-delay:-1.3s}.t3{animation-duration:${f.isFinished ? 3.5 : 3.3}s;animation-delay:-.4s}
@keyframes tw{0%,100%{opacity:1}50%{opacity:${f.isFinished ? 0.8 : 0.3}}}
@media (prefers-reduced-motion: reduce){.t0,.t1,.t2,.t3{animation:none}}
</style>
<defs><clipPath id="c"><rect x="0" y="0" width="${BAR_W}" height="${BAR_H}" rx="${BAR_H / 2}"/></clipPath></defs>
<circle cx="5" cy="${H / 2}" r="4" fill="${color}"/>
<text class="t" ${titleAt} y="${H / 2 + 4.5}" font-family="${FONT}" font-size="13" font-weight="500">${xml(title)}</text>
<g transform="translate(${BAR_X},${y0})">
<rect class="k" width="${BAR_W}" height="${BAR_H}" rx="${BAR_H / 2}"/>
<g clip-path="url(#c)">
<g class="flag"><rect width="${fillW}" height="${FLAG_BLUE_H}" fill="${LIS_PALETTE.b}"/><rect y="${FLAG_BLUE_H}" width="${fillW}" height="${BAR_H - FLAG_BLUE_H}" fill="${FLAG_WHITE}" stroke="${LIS_PALETTE.b}" stroke-width="2"/>${emblem}</g>
<g fill="${color}" opacity="0.45">${faint.join('')}</g>
<g class="tk">${ticks.join('')}</g>
</g>
<rect x="${pillX}" width="${pillW}" height="${BAR_H}" rx="${BAR_H / 2}" fill="${color}"/>
<text x="${pillX + pillW / 2}" y="${BAR_H / 2 + 4}" text-anchor="middle" font-family="${FONT}" font-size="11" font-weight="600" fill="#ffffff">${xml(text)}</text>
</g>
<text class="m" ${percentAt} font-family="${FONT}" font-size="12.5" font-variant-numeric="tabular-nums">${percent}</text>
${CRAB_CSS}${crab(W - CRAB_W + 1, 0, 'other', false, isWorking, 0.8)}
</svg>`
}

// The whole flag in 6 pixel rows, as LIS_PALETTE keys plus `w`: four rows of blue
// with the rainbow arc standing on the white, two rows of white.
const FLAG_ROWS = 6
const HORIZON = 4

const flagGrid = (width: number): string[] => {
  const rows = Array.from({ length: FLAG_ROWS }, (_, y) => Array.from({ length: width }, () => (y < HORIZON ? 'b' : 'w')))
  if (width >= 12) {
    const cx = (width - 1) / 2
    const rx = 0.42 * width
    for (let x = 0; x < width; x++) {
      const dx = (x - cx) / rx
      if (Math.abs(dx) > 1) continue
      const top = Math.round(HORIZON - (HORIZON - 1) * Math.sqrt(1 - dx * dx))
      ;['r', 'y', 'g'].forEach((c, i) => {
        if (top + i < HORIZON) rows[top + i]![x] = c
      })
    }
  }
  return rows.map(r => r.join(''))
}

// The emblem's glyphs at the middle column, one per cell row: the star above the arc,
// the sun inside it, the cross on the white.
const FLAG_GLYPHS: readonly Cell[] = [
  { ch: '★', fg: LIS_PALETTE.y, bg: LIS_PALETTE.b },
  { ch: '✹', fg: LIS_PALETTE.y, bg: LIS_PALETTE.b },
  { ch: '✝', fg: LIS_PALETTE.r, bg: FLAG_WHITE },
]

// Three rows of cells: the flag where the bar is filled, a dim shade beyond.
const flagBar = (r: number, width: number): Cell[][] => {
  const filled = Math.round(width * r)
  const cells = halfBlocks(flagGrid(width), { ...LIS_PALETTE, w: FLAG_WHITE })
  const mid = Math.floor((width - 1) / 2)
  return cells.map((row, i) =>
    row.map((cell, x) => {
      if (x >= filled) return { ch: '░' }
      return width >= 3 && x === mid ? FLAG_GLYPHS[i]! : cell
    }),
  )
}

// One Text per row of the bar, with runs of the same colours joined.
const flagRows = (Text: ElementTable['Text'], cells: Cell[][]) =>
  cells.map((row, i) => {
    const runs: Cell[] = []
    for (const c of row) {
      const last = runs[runs.length - 1]
      if (last && last.ch[0] === c.ch && last.fg === c.fg && last.bg === c.bg) last.ch += c.ch
      else runs.push({ ...c })
    }
    return (
      <Text key={`flag-${i}`}>
        {runs.map((c, x) => (
          <Text key={String(x)} color={c.fg} backgroundColor={c.bg} dimColor={c.ch[0] === '░'}>
            {c.ch}
          </Text>
        ))}
      </Text>
    )
  })

// ---------------------------------------------------------------------------
// Agents panel: every subagent of the session, plus the tasks the flow planned.

const TIER_COLOR: Record<string, string> = {
  fable: D['--color-light-blue-soft']!,
  heavy: D['--color-light-red-soft']!,
  careful: D['--color-light-yellow-default']!,
  medium: D['--color-light-blue-softer']!,
  light: D['--color-light-green-soft']!,
  other: D['--color-light-gray-soft']!,
}

// What each savvy tier runs on, for planned tasks that have no run yet.
const colorOf = (tier: string): string => TIER_COLOR[tier] ?? TIER_COLOR.other!

const TIER_MODEL: Record<string, [model: string, effort: string]> = {
  fable: ['Fable', 'high'],
  heavy: ['Opus', 'xhigh'],
  careful: ['Opus', 'high'],
  medium: ['Opus', 'medium'],
  light: ['Opus', 'low'],
}

// "Opus · xhigh", with the effort word in the panel's language; '' for an unknown tier.
const tierModel = (tier: string): string => {
  const m = TIER_MODEL[tier]
  return m ? `${m[0]} · ${effortWord(m[1])}` : ''
}

// "Opus 5.5 · low" for a run, or just the model when no effort was seen.
const runModel = (a: AgentRun): string => (a.effort ? `${modelName(a.model)} · ${effortWord(a.effort)}` : modelName(a.model))

// USD per million tokens: input, output, cache read, cache write. The first row that
// matches a model id wins, so a release sits above its family.
// The engine reports tokens, not money, so the panel's cost is an estimate. It reports
// one cache-write count with no split by lifetime; writes are priced at the 1-hour
// rate (2x input), which is what Claude Code writes on a subscription.
type Price = [input: number, output: number, cacheRead: number, cacheWrite: number]

const PRICES: [RegExp, Price][] = [
  [/(fable|mythos)-5-1/, [10, 50, 0.25, 20]],
  [/fable|mythos/, [10, 50, 1, 20]],
  [/opus-5-5/, [4, 20, 0.2, 8]],
  [/opus/, [5, 25, 0.5, 10]],
  [/sonnet-5-5/, [2, 10, 0.1, 4]],
  [/sonnet-5/, [2, 10, 0.2, 4]],
  [/sonnet/, [3, 15, 0.3, 6]],
  [/haiku-5-5/, [0.1, 0.5, 0.01, 0.2]],
  [/haiku/, [1, 5, 0.1, 2]],
]

// Haiku 5.5 is priced by prompt length: a request whose prompt (input, cache reads and
// cache writes together) is over 100,000 tokens pays these prices instead.
const HAIKU_LONG_PROMPT = 100_000
const HAIKU_LONG: Price = [0.5, 2.5, 0.05, 1]

type Usage = {
  input_tokens: number
  output_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
}

const priceOf = (model: string, prompt: number): Price => {
  const id = model.toLowerCase()
  if (prompt > HAIKU_LONG_PROMPT && /haiku-5-5/.test(id)) return HAIKU_LONG
  return PRICES.find(([re]) => re.test(id))?.[1] ?? [4, 20, 0.2, 8]
}

// `isRequest` says the usage is one model request, which is what a prompt-length price
// is set by; a turn's sum is priced at the model's ordinary prices.
const costOf = (model: string, u: Usage, isRequest: boolean): number => {
  const prompt = isRequest ? (u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0) : 0
  const [i, o, r, w] = priceOf(model, prompt)
  return (
    ((u.input_tokens || 0) * i +
      (u.output_tokens || 0) * o +
      (u.cache_read_input_tokens || 0) * r +
      (u.cache_creation_input_tokens || 0) * w) /
    1e6
  )
}

// Haiku 4.5 and the Claude 3 models have a 200K window; the rest, Haiku 5.5 included, 1M.
const windowOf = (model: string): number => (/haiku-4|claude-3/i.test(model) ? 200_000 : 1_000_000)

// `savvy-careful`, or `savvy-flow:savvy-careful` when the agents ship in a plugin.
const tierOf = (type: string): string => {
  const bare = type.replace(/^[^:]*:/, '')
  const t = bare.replace(/^savvy-/, '').toLowerCase()
  return Object.hasOwn(TIER_COLOR, t) && bare.startsWith('savvy-') ? t : 'other'
}

const modelName = (id: string): string => {
  const m = /(fable|mythos|opus|sonnet|haiku)-(\d+)(?:-(\d{1,2})(?!\d))?/i.exec(id)
  const [, family = '', major = '', minor] = m ?? []
  if (!family) return id.replace(/^claude-/, '').replace(/\[.*\]$/, '') || '—'
  return `${family.charAt(0).toUpperCase()}${family.slice(1).toLowerCase()} ${major}${minor ? '.' + minor : ''}`
}

const norm = (s: string): string => s.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim()

const fmtTokens = (n: number): string =>
  n >= 1e6 ? `${(n / 1e6).toFixed(1)}M` : n >= 1e3 ? `${Math.round(n / 1e3)}k` : `${Math.round(n)}`

const fmtCost = (usd: number): string => `$${usd < 10 ? usd.toFixed(2) : usd.toFixed(1)}`

const fmtTime = (ms: number): string => {
  const s = Math.max(0, Math.round(ms / 1000))
  const h = Math.floor(s / 3600)
  const m = Math.floor((s % 3600) / 60)
  const ss = String(s % 60).padStart(2, '0')
  return h ? `${h}:${String(m).padStart(2, '0')}:${ss}` : `${m}:${ss}`
}

const elapsed = (a: AgentRun, at: number): number => (a.endedAt ?? Math.max(at, a.startedAt)) - a.startedAt

type Planned = PlannedTask & { n: number }

const plannedOf = (f: Flow | null, list: AgentRun[]): Planned[] => {
  if (!f || f.isFinished) return []
  const started = new Set(list.map(a => norm(a.description)))
  return (f.tasks ?? []).map((t, i) => ({ ...t, n: i + 1 })).filter(t => !started.has(norm(t.title)))
}

const totals = (list: AgentRun[], at: number) => {
  const cost = list.reduce((s, a) => s + a.costUsd, 0)
  const tokens = list.reduce((s, a) => s + a.tokens, 0)
  const start = Math.min(...list.map(a => a.startedAt))
  const end = Math.max(...list.map(a => a.endedAt ?? Math.max(at, a.startedAt)))
  return { cost, tokens, time: list.length ? end - start : 0 }
}

// --- desktop drawings: each row is one SVG, as the band above the prompt is.

// The pane's backdrop: a dotted grid as tall as the content laid over it; the
// row SVGs are transparent, so it shows through between their marks.
const GRID_STEP = 16
// A Text or Button row on the desktop is about 20px; the grid errs taller.
const LINE_H = 24
// The engine refuses an Svg taller than 4096px, so a long grid is stacked from
// tiles of at most this height; a multiple of GRID_STEP keeps the dots aligned.
const GRID_TILE = 4096
const gridTiles = (H: number) => Array.from({ length: Math.ceil(H / GRID_TILE) }, (_, i) => Math.min(GRID_TILE, H - i * GRID_TILE))
const gridSvg = (W: number, H: number) => `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
<style>.d{fill:${L['--color-light-gray-soft']}}@media (prefers-color-scheme: dark){.d{fill:${D['--color-dark-gray-softer']}}}</style>
<defs><pattern id="g" width="${GRID_STEP}" height="${GRID_STEP}" patternUnits="userSpaceOnUse"><circle class="d" cx="${GRID_STEP / 2}" cy="${GRID_STEP / 2}" r="1"/></pattern></defs>
<rect width="${W}" height="${H}" fill="url(#g)"/>
</svg>`

const PANE_CSS = `<style>
.t{fill:${L['--color-text-default']}}.s{fill:${L['--color-text-secondary']}}.m{fill:${L['--color-text-placeholder']}}.k{fill:${L['--color-light-gray-softer']}}.ln{stroke:${L['--color-light-gray-soft']}}.tile{fill:${L['--color-light-gray-softest']}}
@media (prefers-color-scheme: dark){.t{fill:${D['--color-text-default']}}.s{fill:${D['--color-text-secondary']}}.m{fill:${D['--color-text-placeholder']}}.k{fill:${D['--color-dark-gray-soft']}}.ln{stroke:${D['--color-dark-gray-softer']}}.tile{fill:${D['--color-dark-gray-default']}}}
.live{animation:p 1.6s ease-in-out infinite}@keyframes p{50%{opacity:.3}}
@media (prefers-reduced-motion: reduce){.live{animation:none}}
</style>`

// Pixel Lis (./lis) on the 30×28 grid of DockCrab's (Clawdy) crab, one DockCrab costume
// per tier. The body keeps the flag colours; the tier's color lives in the costume's accent.
const INK = LIS_PALETTE.k

// `cls` puts a pixel in a named group: `bd` (the default) is the body and its
// costume, `la`/`lb` the leg pairs, anything else a prop with its own motion.
type Fill = (x: number, y: number, w: number, h: number, c: string, cls?: string) => void

const stamp = (f: Fill, x: number, y: number, rows: string[], map: Record<string, string>, cls?: string): void =>
  rows.forEach((row, dy) => [...row].forEach((ch, dx) => map[ch] && f(x + dx, y + dy, 1, 1, map[ch] ?? '', cls)))

// `armCls` lets a raised arm travel with the prop it holds.
const lisBody = (f: Fill, armFront = 0, armCls?: string): void => {
  stamp(f, 3, 4, LIS_BODY, LIS_PALETTE)
  f(23, 14 + armFront, 4, 3, LIS_PALETTE.b, armCls)
  f(23, 17 + armFront, 4, 1, LIS_PALETTE.o, armCls)
  f(7, 22, 2, 4, LIS_PALETTE.b, 'la')
  f(17, 22, 2, 4, LIS_PALETTE.b, 'la')
  f(11, 22, 2, 4, LIS_PALETTE.b, 'lb')
  f(21, 22, 2, 4, LIS_PALETTE.b, 'lb')
}

// Pure CSS, run by the compositor: no redraws. Periods divide one second, so the
// once-a-second redraw of a running row restarts them in phase. Every crab walks;
// each costume adds its prop's own motion on top.
const CRAB_CSS = `<style>
.run .la{animation:st .5s steps(1) infinite}.run .lb{animation:st .5s steps(1) infinite -.25s}
.run .bd{animation:bob .5s steps(1) infinite -.125s}
.run g{transform-box:fill-box}
@keyframes st{50%{transform:translateY(-1px)}}@keyframes bob{50%{transform:translateY(1px)}}
.c-fable.run{animation:float 1s ease-in-out infinite}
.c-fable.run .la,.c-fable.run .lb,.c-fable.run .bd{animation:none}
.c-fable.run .ant{animation:blink 1s steps(1) infinite}
.c-fable.run .star{animation:blink .5s steps(1) infinite -.25s}
@keyframes float{50%{transform:translateY(-2px)}}@keyframes blink{50%{opacity:.15}}
.c-heavy.run .it{animation:scan 1s steps(1) infinite}
.c-heavy.run .gl{animation:blink 1s steps(1) infinite -.5s}
@keyframes scan{25%{transform:translate(-1px,1px)}50%{transform:translate(-2px,2px)}75%{transform:translate(-1px,1px)}}
.c-careful.run .it{transform-origin:100% 100%;animation:twist .5s ease-in-out infinite}
@keyframes twist{50%{transform:rotate(-35deg)}}
.c-medium.run .pan{transform-origin:0 50%;animation:tilt 1s ease-in-out infinite}
.c-medium.run .egg{animation:flip 1s ease-in-out infinite}
@keyframes tilt{20%,40%{transform:rotate(-12deg)}}@keyframes flip{30%{transform:translateY(-5px) scaleY(-1)}60%{transform:translateY(0)}}
.c-light.run .la{animation-duration:.25s}.c-light.run .lb{animation-duration:.25s;animation-delay:-.125s}
.c-light.run .flag{transform-origin:0 50%;animation:wave .25s steps(1) infinite}
@keyframes wave{50%{transform:skewY(-12deg) scaleX(.85)}}
.c-explore.run .it{transform-origin:50% 100%;animation:fence .5s ease-in-out infinite}
@keyframes fence{50%{transform:rotate(25deg)}}
@media (prefers-reduced-motion: reduce){.run,.run g{animation:none!important}}
</style>`

const COSTUMES: Record<string, (f: Fill, t: string) => void> = {
  // Fable: astronaut in a glass dome; floats instead of walking, the antenna and the star blink.
  fable: (f, t) => {
