  init: { verb: 'init', running: 'iniciando repositório', done: 'repositório iniciado', tone: 'green', icon: ICON.git, init: true },
  clone: { verb: 'clone', running: 'clonando', done: 'clonado', tone: 'blue', icon: ICON.pull, init: true },
